use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
    RetryConfig {
        max_attempts,
        base_delay_ms,
        max_delay_ms,
    }
}

#[test]
fn retries_transient_errors_with_bounded_exponential_delays() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config(4, 25, 60), &mut sleeper, || {
        calls += 1;
        if calls < 4 {
            Err(RetryError::Transient("temporary outage".into()))
        } else {
            Ok(())
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 4);
    assert_eq!(sleeper.sleeps, vec![25, 50, 60]);
}

#[test]
fn permanent_errors_return_without_retrying() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config(5, 10, 100), &mut sleeper, || {
        calls += 1;
        Err(RetryError::Permanent("invalid job".into()))
    });

    assert_eq!(result, Err(RetryError::Permanent("invalid job".into())));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn max_attempts_includes_the_first_call() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config(3, 1, 10), &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("still unavailable".into()))
    });

    assert_eq!(result, Err(RetryError::Transient("still unavailable".into())));
    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps, vec![1, 2]);
}

#[test]
fn large_attempt_numbers_saturate_without_overflow() {
    let mut sleeper = FakeSleeper::default();

    let result = run_job(&config(70, u64::MAX, 123), &mut sleeper, || {
        Err(RetryError::Transient("still unavailable".into()))
    });

    assert!(matches!(result, Err(RetryError::Transient(_))));
    assert_eq!(sleeper.sleeps.len(), 69);
    assert!(sleeper.sleeps.iter().all(|&delay| delay == 123));
}

#[test]
fn zero_attempt_budget_still_makes_one_call() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config(0, 10, 100), &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("unavailable".into()))
    });

    assert!(matches!(result, Err(RetryError::Transient(_))));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

